"""Prepared-db literal with real desktop media-query contexts, never pseudo breakpoint overrides."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const esc=','const icons=','const icon=','const t=','const btn=','const notice=','function trialPreparation(')))
data=[('sample','migration_test','trial.example.invalid'),('latin','tenant_'+'migration_records_v1_'*10,'db-'*24+'example.invalid'),('korean','마이그레이션검증시험데이터베이스_'*6,'시험서버-'*20+'example.invalid'),('empty','','')]
cases=[dict(id=f'{lang}-{viewport}-{width}-{dbms}-{name}',lang=lang,parentWidth=width,viewportWidth=viewport,dbms=dbms,database=db,host=host)for lang in ['ko','en']for viewport in [1110,1280]for width in [656,904]for dbms in ['SQL Server','PostgreSQL','SQLite']for name,db,host in data]
(o/'prepareddb-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
frame='''<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="http://10.211.55.2:8768/prepareddb-original.css"><style>.fixture{position:absolute;left:30px;top:30px;display:flex}.prepared-db{animation:none!important}</style><div class="fixture" id="fixture"></div><script>let lang=CASE.lang,state={selected:new Set(['trial']),trial:{ready:true,db:CASE.database,host:CASE.host},dbms:CASE.dbms};'''+defs+''';const f=document.getElementById('fixture');f.style.width=CASE.parentWidth+'px';const temporary=document.createElement('div');temporary.innerHTML=trialPreparation();f.append(temporary.querySelector('.prepared-db'));window.fixtureReady=document.fonts.ready;</script>'''
read='''function read(f){const e=f.contentDocument.querySelector('.prepared-db'),rect=e.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-rect.x,y:b.y-rect.y,width:b.width,height:b.height}},style=x=>f.contentWindow.getComputedStyle(x),s=style(e);return{id:f.dataset.id,width:rect.width,height:rect.height,parts:{dbIcon:box(e.children[0]),body:box(e.children[1]),name:box(e.querySelector('strong')),meta:box(e.querySelector('span')),hint:box(e.querySelector('small')),checkIcon:box(e.children[2])},texts:{name:e.querySelector('strong').textContent,meta:e.querySelector('span').textContent,hint:e.querySelector('small').textContent},palette:{background:s.backgroundColor,border:s.borderLeftColor,name:style(e.querySelector('strong')).color,meta:style(e.querySelector('span')).color,dbIcon:style(e.children[0]).color,checkIcon:style(e.children[2]).color},radius:s.borderRadius,role:e.getAttribute('role')};}'''
script='const cases='+json.dumps(cases,ensure_ascii=False)+';const frame='+json.dumps(frame,ensure_ascii=False).replace('</','<\\/')+''';const ready=[];for(const c of cases){const f=document.createElement('iframe');f.dataset.id=c.id;f.style.width=c.viewportWidth+'px';f.style.height='720px';f.srcdoc=frame.replaceAll('CASE',JSON.stringify(c));ready.push(new Promise(res=>f.onload=async()=>{await f.contentWindow.fixtureReady;res()}));document.getElementById('fixtures').append(f)}'''+read+'''document.getElementById('prepareddb-record').onclick=async()=>{await Promise.all(ready);const response=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:[...document.querySelectorAll('iframe')].map(read)})});if(!response.ok)throw Error('Evidence failed');document.getElementById('prepareddb-record').textContent='PreparedDb recorded'};'''
(o/'prepareddb.html').write_text('<!doctype html><meta charset="utf-8"><title>PreparedDb · original isolation</title><style>iframe{position:absolute;left:0;top:100px;border:0}iframe:not(:first-child){visibility:hidden}#prepareddb-record{position:fixed;left:30px;top:20px}</style><button id="prepareddb-record">Record PreparedDb</button><div id="fixtures"></div><script>'+script+'</script>')
for p in [o/'prepareddb-cases.json',r/'docs/replica/source/prepareddb-cases.json']:p.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
print(len(cases),'independent desktop PreparedDb cases')
